import base64
import io
import json
import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _read_input_bytes(document: Any) -> bytes:
    if document is None:
        raise ValueError("document must not be None")

    if isinstance(document, bytes):
        return document

    if isinstance(document, str):
        if os.path.exists(document):
            with open(document, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(document, validate=True)
        except Exception:
            return document.encode("utf-8")

    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data

    raise TypeError("Unsupported document input type")


def _result_to_kv_pairs(result: Any) -> List[Dict[str, Optional[str]]]:
    kv_pairs: List[Dict[str, Optional[str]]] = []

    key_values = getattr(result, "key_value_pairs", None) or []
    for kv in key_values:
        key_content = None
        value_content = None

        key = getattr(kv, "key", None)
        value = getattr(kv, "value", None)

        if key is not None:
            key_content = getattr(key, "content", None)
        if value is not None:
            value_content = getattr(value, "content", None)

        if key_content is not None or value_content is not None:
            kv_pairs.append({"key": key_content, "value": value_content})

    return kv_pairs


def extract_key_value_pairs(document: Any, model_id: str = "prebuilt-document") -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set"
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    data = _read_input_bytes(document)

    poller = client.begin_analyze_document(
        model_id=model_id,
        body=data,
        content_type="application/octet-stream",
    )
    result = poller.result()

    kv_pairs = _result_to_kv_pairs(result)

    pages = []
    for page in getattr(result, "pages", []) or []:
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
            }
        )

    return {
        "key_value_pairs": kv_pairs,
        "pages": pages,
        "raw_result": result.to_dict() if hasattr(result, "to_dict") else None,
    }
